BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "footnotes" (
	"footnote"	INTEGER NOT NULL,
	"paragraph"	INTEGER NOT NULL,
	"item_per_paragraph"	INTEGER NOT NULL,
	"sentence"	INTEGER NOT NULL,
	"word_per_paragraph"	INTEGER NOT NULL,
	"word_per_sentence"	INTEGER NOT NULL,
	"item_type"	TEXT NOT NULL,
	"item"	TEXT NOT NULL,
	"item_interlinear"	TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "info" (
	"key"	TEXT NOT NULL,
	"value"	TEXT,
	PRIMARY KEY("key")
);
CREATE TABLE IF NOT EXISTS "lemmas" (
	"term"	TEXT NOT NULL,
	"lemma"	TEXT NOT NULL,
	PRIMARY KEY("term","lemma")
);
CREATE TABLE IF NOT EXISTS "words" (
	"chapter"	INTEGER NOT NULL,
	"paragraph"	INTEGER NOT NULL,
	"item_per_paragraph"	INTEGER NOT NULL,
	"sentence"	INTEGER NOT NULL,
	"word_per_paragraph"	INTEGER NOT NULL,
	"word_per_sentence"	INTEGER NOT NULL,
	"item_type"	TEXT NOT NULL DEFAULT "",
	"start_tags"	TEXT NOT NULL DEFAULT "",
	"start_punctuation"	TEXT NOT NULL DEFAULT "",
	"item"	TEXT NOT NULL DEFAULT "",
	"end_punctuation"	TEXT NOT NULL DEFAULT "",
	"end_tags"	TEXT NOT NULL DEFAULT "",
	"start_punctuation_interlinear"	TEXT NOT NULL DEFAULT "",
	"item_interlinear"	TEXT NOT NULL DEFAULT "",
	"end_punctuation_interlinear"	TEXT NOT NULL DEFAULT "",
	"lowercase_item"	TEXT NOT NULL DEFAULT ""
);
COMMIT;
